        image: "https://firebasestorage.googleapis.com/v0/b/era-genetica-db.firebasestorage.app/o/Characters%2F03%20-%20Oddy%20Uchiha%2FTecnicas%2F02%20-%20Enton%3A%20Amaterasu%20Ry%C5%ABka%20no%20Nint%C5%8D.png?alt=media"
