        image: "https://firebasestorage.googleapis.com/v0/b/era-genetica-db.firebasestorage.app/o/Characters%2F04%20-%20Katsumi%20Hyuga%2FTecnicas%2F06%20-%20Fujogan%3A%20Kuchiyose%20Profana.png?alt=media"
