        image: "https://firebasestorage.googleapis.com/v0/b/era-genetica-db.firebasestorage.app/o/Characters%2F04%20-%20Katsumi%20Hyuga%2FTecnicas%2F08%20-%20Juuken%3A%20J%C5%ABho%20S%C5%8Dshiken.png?alt=media"
